#include <QThread>
#include <QTimer>

class Updater : public QObject
{
    Q_OBJECT
public:
    Updater(QObject* parent = Q_NULLPTR) : QObject(parent) {}

signals:
    void updateValue(QPointF value);

private slots:
    void run();
};

class Data : public QObject
{
    Q_OBJECT
    Q_PROPERTY(QPointF GetValue READ GetValue NOTIFY sgnl_ValueChanged)

public:
    Data(QObject* parent = Q_NULLPTR, Updater* updater = nullptr)
        : QObject(parent), mUpdater(updater)
    {
        if (mUpdater)
        {
            mUpdater->connect(mUpdater, &Updater::updateValue, this, &Data::updateValue);
        }
    }

    QPointF GetValue() const { return m_Value; }

private:
    QTimer* m_Timer;
    QPointF m_Value;
    Updater* mUpdater;

signals:
    void sgnl_ValueChanged();

private slots:
    void slt_Timeout();
    void updateValue(QPointF value);
};

void Data::slt_Timeout()
{
    // Update the value periodically
    m_Value = mUpdater->getValue();
    emit sgnl_ValueChanged();
}

void Data::updateValue(QPointF value)
{
    // Update the value from the Updater
    m_Value = value;
    emit sgnl_ValueChanged();
}

void Updater::run()
{
    QThread::currentThread()->start();
    while (true)
    {
        // Periodically update the value
        emit updateValue(QPointF(100 * qrand() / RAND_MAX, 100 * qrand() / RAND_MAX));
        QThread::currentThread()->msleep(1000); // wait for 1 second
    }
}
