        // Rotate the hips based on the headset rotation and controller rotations
        Vector3 headForward = headRot * Vector3.forward;
        Vector3 hipsForward = new Vector3(headForward.x, 0f, headForward.z).normalized;
        hips.rotation = Quaternion.LookRotation(hipsForward, Vector3.up);

        Quaternion hipsRot = Quaternion.identity;
        hipsRot *= headRot;
        hipsRot *= Quaternion.Euler(0f, 0f, animator.GetFloat("HipRotation"));
        hipsRot *= Quaternion.Euler(animator.GetFloat("LeftHandRotation"), 0f, 0f);
        hipsRot *= Quaternion.Euler(animator.GetFloat("RightHandRotation"), 0f, 0f);

