        // Detect when the player bows and adjust the hips rotation accordingly
        float bowAngle = animator.GetFloat("BowAngle");
        if (bowAngle > 0.1f)
        {
            hips.rotation *= Quaternion.Euler(0f, 0f, bowAngle);
        }
    }
}
