class Balancer {
  constructor(items) {
    this.items = items;
    this.unusedItems = items;
  }

  select(filterFn) {
    const filteredItems = this.unusedItems.filter(filterFn);
    if (filteredItems.length === 0) {
      throw new Error('No items left to select');
    }
    const mostUnusedItem = filteredItems.reduce((a, b) => {
      return a.unusedCount > b.unusedCount ? a : b;
    });
    mostUnusedItem.unusedCount = 0;
    this.unusedItems = this.unusedItems.filter(item => item !== mostUnusedItem);
    return mostUnusedItem;
  }
}

