#include <iostream>
#include <vector>
#include <thread>
#include <mutex>
#include <condition_variable>

// A reusable barrier implementation using std::mutex and std::condition_variable
class ReusableBarrier {
public:
    ReusableBarrier(int num_threads) : num_threads_(num_threads), count_(0) {}

    void wait() {
        std::unique_lock<std::mutex> lock(mutex_);
        barrier_cv_.wait(lock, [this] { return count_ == num_threads_; });
    }

    void exit() {
        std::unique_lock<std::mutex> lock(mutex_);
        count_++;
        if (count_ == num_threads_) {
            barrier_cv_.notify_all();
        }
    }

private:
    int num_threads_;
    int count_;
    std::mutex mutex_;
    std::condition_variable barrier_cv_;
};

// A worker function that waits at the barrier and then exits
void worker(ReusableBarrier& barrier) {
    barrier.wait();
    std::cout << "Worker thread " << std::this_thread::get_id() << " exiting" << std::endl;
    barrier.exit();
}

int main() {
    const int num_threads = 4;
    ReusableBarrier barrier(num_threads);

    std::vector<std::thread> threads;
    for (int i = 0; i < num_threads; ++i) {
        threads.emplace_back(worker, barrier);
    }

    // Wait for all threads to finish
    for (auto& t : threads) {
        t.join();
    }

    return 0;
}
