        for (String part : commentParts) {
            List<String> commentsForPart = new ArrayList<>();
            for (String comment : performanceEvaluation.getComments().split("\\n")) {
                if (comment.startsWith(part)) {
                    commentsForPart.add(comment);
                }
            }
            sortedComments.addAll(commentsForPart);
        }

        // Join the sorted comments into a single string
        return String.join("\n", sortedComments);
    }
}

