from typing import List, Any

class UniqueList(List[Any]):
    def __init__(self, *args):
        super().__init__(*args)
        self.seen = set(self)

    def __setitem__(self, index: int, value: Any) -> None:
        if value in self.seen:
            raise ValueError(f"Value {value} already exists in UniqueList")
        self.seen.discard(self[index])
        self.seen.add(value)
        super().__setitem__(index, value)

    def __setslice__(self, i: int, j: int, iterable: List[Any]) -> None:
        for value in iterable:
            if value in self.seen:
                raise ValueError(f"Value {value} already exists in UniqueList")
        for index in range(i, j):
            self.seen.discard(self[index])
        for value in iterable:
            self.seen.add(value)
        super().__setslice__(i, j, iterable)

    def __delitem__(self, index: int) -> None:
        self.seen.discard(self[index])
        super().__delitem__(index)

    def __delslice__(self, i: int, j: int) -> None:
        for index in range(i, j):
            self.seen.discard(self[index])
        super().__delslice__(i, j)

    def append(self, value: Any) -> None:
        if value in self.seen:
            raise ValueError(f"Value {value} already exists in UniqueList")
        self.seen.add(value)
        super().append(value)

    def extend(self, iterable: List[Any]) -> None:
        for value in iterable:
            if value in self.seen:
                raise ValueError(f"Value {value} already exists in UniqueList")
        for value in iterable:
            self.seen.add(value)
        super().extend(iterable)

    def insert(self, index: int, value: Any) -> None:
        if value in self.seen:
            raise ValueError(f"Value {value} already exists in UniqueList")
        self.seen.add(value)
        super().insert(index, value)
